const data = $input.first().json.body || $input.first().json;
const keyword = data.keyword || 'Sans titre';
const sujet = data.sujet || keyword;
const intent = data.intent || 'informationnelle';
const pilier = data.pilier || 'SEO';
const objectif = data.objectif || '—';
const audience = data.audience || '—';
const opportunite = data.opportunite || '—';
const ps = data.publish_score || 0;
const emoji = data.emoji || '⚪';
const priority = data.priority || 'C';
const diag = data.diag || '—';
const weakest = data.weakest || '—';
const scoreSeo = (data.audit_seo && data.audit_seo.score_seo) || 0;
const scoreConv = (data.audit_conv && data.audit_conv.score_conversion) || 0;
const scoreAuth = (data.audit_auth && data.audit_auth.score_autorite) || 0;
const docId = data.documentId || '';
const docUrl = docId ? `https://docs.google.com/document/d/${docId}/edit` : null;
const generatedAt = data.generated_at || new Date().toISOString().split('T')[0];
const clusterRole = (data.cluster && data.cluster.role) || 'Satellite';
const satellites = ((data.cluster && data.cluster.satellites) || []).map(s => s.titre).join(', ') || '—';
const maillage = ((data.cluster && data.cluster.maillage) || []).join(' | ') || '—';
const psColor = ps >= 85 ? 'green_background' : (ps >= 75 ? 'yellow_background' : 'red_background');
const psIcon = ps >= 85 ? '✅' : (ps >= 75 ? '🟡' : '🔴');
const properties = {
  'Sujet': { title: [{ text: { content: sujet } }] },
  'Mot-clé': { rich_text: [{ text: { content: keyword } }] },
  'Intent': { select: { name: intent } },
  'Type': { select: { name: clusterRole } },
  'Pilier': { select: { name: pilier } },
  'Objectif': { rich_text: [{ text: { content: objectif } }] },
  'Score SEO': { number: scoreSeo },
  'Score Conversion': { number: scoreConv },
  'Score Autorité': { number: scoreAuth },
  'Publish Score': { number: ps },
  'Priorité': { select: { name: priority } },
  'Statut': { select: { name: 'Généré ✓' } },
  'Date création': { date: { start: generatedAt } }
};
if (docUrl) properties['Lien Google Doc'] = { url: docUrl };
const rt = (content) => [{ type: 'text', text: { content } }];
const children = [
  {
    type: 'callout',
    callout: {
      rich_text: rt(`Publish Score : ${ps}/100 ${emoji}  |  ${diag}  |  Priorité : ${priority}`),
      icon: { emoji: psIcon },
      color: psColor
    }
  },
  { type: 'divider', divider: {} },
  { type: 'heading_2', heading_2: { rich_text: rt('1️⃣ Stratégie') } },
  {
    type: 'paragraph',
    paragraph: {
      rich_text: rt(`Mot-clé : ${keyword}\nIntent : ${intent}\nPublic : ${audience}\nObjectif : ${objectif}\nType CTA : ${opportunite}`)
    }
  },
  { type: 'divider', divider: {} },
  { type: 'heading_2', heading_2: { rich_text: rt('4️⃣ Scores détaillés') } },
  {
    type: 'paragraph',
    paragraph: {
      rich_text: rt(`Score SEO        : ${scoreSeo}/100\nScore Conversion : ${scoreConv}/100\nScore Autorité   : ${scoreAuth}/100\n\nPublish Score    : ${ps}/100 ${emoji}\nBloc faible      : ${weakest}`)
    }
  },
  { type: 'divider', divider: {} },
  { type: 'heading_2', heading_2: { rich_text: rt('5️⃣ Cluster sémantique') } },
  {
    type: 'paragraph',
    paragraph: {
      rich_text: rt(`Position   : ${clusterRole}\nSatellites : ${satellites}\nMaillage   : ${maillage}`)
    }
  }
];
if (docUrl) {
  children.push({ type: 'divider', divider: {} });
  children.push({
    type: 'bookmark',
    bookmark: { url: docUrl, caption: rt('Ouvrir dans Google Docs') }
  });
}
const notionPayload = {
  parent: { database_id: 'VOTRE_NOTION_DATABASE_ID' },
  properties,
  children
};
return [{ json: { notionPayload, keyword, ps, priority } }];

const notionPage = $input.first().json;
const prev = $('Code - Build Notion Payload').first().json;
const pageId = notionPage.id || '';
const pageUrl = notionPage.url || `https://www.notion.so/${pageId.replace(/-/g, '')}`;
return [{ json: {
  success: true,
  notion_page_id: pageId,
  notion_page_url: pageUrl,
  keyword: prev.keyword,
  publish_score: prev.ps,
  priority: prev.priority
} }];
